/**
 * Pre-Classifier — hard-coded rules that bypass Claude entirely.
 *
 * Checks the sender against two sources:
 *   1. KNOWN_SENDERS in rules.js (static, committed to repo)
 *   2. "learned-rules" Sheet tab (dynamic, auto-generated by the learner)
 *
 * If a match is found, returns a full classification object immediately.
 * If no match, returns null — the email goes to Claude as usual.
 *
 * This saves tokens and is instant for known senders.
 */

const LEARNED_RULES_TAB = 'learned-rules';

/**
 * Try to classify an email without calling Claude.
 *
 * @param {GmailMessage} message - The Gmail message to classify
 * @returns {Object|null} Classification result, or null if no rule matches
 */
function preClassify(message) {
  const senderHeader = message.getFrom();
  const senderEmail = normalizeEmailAddress_(senderHeader);
  const senderDomain = extractDomain_(senderEmail);

  // 1. Check static KNOWN_SENDERS (exact email first, then domain)
  let rule = KNOWN_SENDERS[senderEmail] || KNOWN_SENDERS[senderDomain];

  // 2. If no static match, check learned rules from Sheet
  if (!rule) {
    rule = lookupLearnedRule_(senderDomain);
  }

  if (!rule) {
    return null;
  }

  // Build a full classification object with defaults for missing fields
  return {
    mailbox_action: rule.mailbox_action || 'No Known Action',
    action_type: rule.action_type || 'Archive',
    sub_action_type: rule.sub_action_type || null,
    category: rule.category || 'Automated',
    person_or_bot: rule.person_or_bot || 'Bot',
    priority: rule.priority || 'Low',
    ai_summary: rule.ai_summary || `Auto-classified: ${senderDomain}`,
    ai_suggested_reply: rule.ai_suggested_reply || null,
    ai_next_step: rule.ai_next_step || 'Archive.',
    tags: rule.tags || '',
    _source: rule._source || 'known-sender'
  };
}

/**
 * Extract domain from a normalized email address.
 */
function extractDomain_(email) {
  const parts = String(email || '').split('@');
  return parts.length === 2 ? parts[1] : '';
}

// ============================================================
// LEARNED RULES (from Sheet)
// ============================================================

/** @type {Object|null} Cache for learned rules (loaded once per run) */
var _learnedRulesCache = null;

/**
 * Look up a sender domain in the learned-rules Sheet tab.
 * Loaded once per trigger run and cached in memory.
 *
 * @param {string} domain - Sender domain to look up
 * @returns {Object|null} Classification rule, or null
 */
function lookupLearnedRule_(domain) {
  if (!domain) return null;

  if (_learnedRulesCache === null) {
    _learnedRulesCache = loadLearnedRules_();
  }

  const rule = _learnedRulesCache[domain];
  if (rule) {
    rule._source = 'learned';
  }
  return rule || null;
}

/**
 * Load all learned rules from the Sheet into a domain→rule map.
 * Returns empty object if Sheet or tab doesn't exist.
 */
function loadLearnedRules_() {
  const rules = {};

  try {
    const sheetId = PropertiesService.getScriptProperties().getProperty('LOG_SHEET_ID');
    if (!sheetId) return rules;

    const ss = SpreadsheetApp.openById(sheetId);
    const sheet = ss.getSheetByName(LEARNED_RULES_TAB);
    if (!sheet) return rules;

    const data = sheet.getDataRange().getValues();
    // Header: Domain, Category, Priority, Person/Bot, Action, Tags, AI Summary, AI Next Step, Confidence, Sample Count, Last Updated

    for (let i = 1; i < data.length; i++) {
      const row = data[i];
      const domain = String(row[0] || '').trim().toLowerCase();
      if (!domain) continue;

      rules[domain] = {
        category: row[1] || 'Automated',
        priority: row[2] || 'Low',
        person_or_bot: row[3] || 'Bot',
        action_type: row[4] || 'Archive',
        tags: row[5] || '',
        ai_summary: row[6] || `Auto-classified: ${domain}`,
        ai_next_step: row[7] || 'Archive.'
      };
    }
  } catch (e) {
    Logger.log('Failed to load learned rules: ' + e.message);
  }

  return rules;
}
